import React, { useState } from 'react';
import BlocoEtapaVisual from './BlocoEtapaVisual';

export default function EditorEtapasAvancado_Modular() {
  const [fluxos, setFluxos] = useState([
    { id: 1, nome: 'Fluxo Principal', ativo: true, atualizado: '13/04/2025 15:42' },
    { id: 2, nome: 'Atendimento Noite', ativo: false, atualizado: '11/04/2025 19:10' }
  ]);
  const [fluxoSelecionado, setFluxoSelecionado] = useState(fluxos[0]);
  const [modoAvancado, setModoAvancado] = useState(false);
  const [etapas, setEtapas] = useState([
    { id: 1 }, { id: 2 }
  ]);

  const novoFluxo = () => {
    const novo = {
      id: Date.now(),
      nome: `Novo Fluxo ${fluxos.length + 1}`,
      ativo: false,
      atualizado: new Date().toLocaleString()
    };
    setFluxos([...fluxos, novo]);
    setFluxoSelecionado(novo);
  };

  const adicionarEtapa = () => {
    const nova = {
      id: etapas.length + 1
    };
    setEtapas([...etapas, nova]);
  };

  return (
    <div className="min-h-screen flex bg-gray-100 font-sans">
      <aside className="w-64 bg-white shadow px-4 py-6 border-r">
        <h2 className="text-lg font-bold mb-4">Meus Fluxos</h2>
        <ul className="space-y-2">
          {fluxos.map((fluxo) => (
            <li
              key={fluxo.id}
              className={`p-2 rounded cursor-pointer border ${fluxoSelecionado.id === fluxo.id ? 'bg-blue-100' : 'bg-gray-50'}`}
              onClick={() => setFluxoSelecionado(fluxo)}
            >
              <div className="flex justify-between items-center">
                <span className="font-medium text-sm">{fluxo.nome}</span>
                {fluxo.ativo && <span className="text-xs text-green-600">Ativo</span>}
              </div>
              <p className="text-xs text-gray-400">Atualizado em {fluxo.atualizado}</p>
            </li>
          ))}
        </ul>
        <button
          onClick={novoFluxo}
          className="mt-6 w-full bg-blue-600 text-white py-2 rounded hover:bg-blue-700 text-sm"
        >
          + Novo Fluxo
        </button>
      </aside>

      <main className="flex-1 p-6">
        <header className="flex justify-between items-center mb-6">
          <div>
            <h1 className="text-xl font-bold">Editor: {fluxoSelecionado.nome}</h1>
            <p className="text-sm text-gray-500">Última publicação: {fluxoSelecionado.atualizado}</p>
          </div>
          <div className="flex gap-3">
            <button className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700 text-sm">Exportar JSON</button>
            <button className="bg-gray-300 text-sm px-4 py-2 rounded hover:bg-gray-400">Importar JSON</button>
            <button className="bg-yellow-500 text-white text-sm px-4 py-2 rounded hover:bg-yellow-600">Simular Atendimento</button>
          </div>
        </header>

        <div className="mb-4">
          <label className="text-sm font-medium mr-2">Modo:</label>
          <button
            onClick={() => setModoAvancado(false)}
            className={`px-4 py-2 rounded-l ${!modoAvancado ? 'bg-blue-600 text-white' : 'bg-gray-200'}`}
          >
            Visual
          </button>
          <button
            onClick={() => setModoAvancado(true)}
            className={`px-4 py-2 rounded-r ${modoAvancado ? 'bg-blue-600 text-white' : 'bg-gray-200'}`}
          >
            Avançado (JSON)
          </button>
        </div>

        {modoAvancado ? (
          <textarea
            className="w-full border p-4 rounded h-64 bg-white text-sm font-mono"
            placeholder="Cole aqui seu fluxo em JSON"
          />
        ) : (
          <div className="space-y-4">
            {etapas.map((etapa) => (
              <BlocoEtapaVisual key={etapa.id} etapaId={etapa.id} />
            ))}
            <button
              onClick={adicionarEtapa}
              className="bg-blue-500 text-white px-4 py-2 rounded hover:bg-blue-600 text-sm"
            >
              + Nova Etapa
            </button>
          </div>
        )}
      </main>
    </div>
  );
}
